import{_ as t,o as a,c as r,a0 as i}from"./chunks/framework.Bmhw_dvp.js";const g=JSON.parse('{"title":"Project Management","description":"Workspace structure, script parsing patterns, and cloning logic.","frontmatter":{"isInternal":true,"type":"Specification","title":"Project Management","description":"Workspace structure, script parsing patterns, and cloning logic.","tags":["features","specs","architecture"]},"headers":[],"relativePath":"specs/features/project_management.md","filePath":"specs/features/project_management.md"}'),n={name:"specs/features/project_management.md"};function o(c,e,s,l,d,p){return a(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="project-management-technical-specification" tabindex="-1">Project Management Technical Specification <a class="header-anchor" href="#project-management-technical-specification" aria-label="Permalink to &quot;Project Management Technical Specification&quot;">​</a></h1><h2 id="_1-overview" tabindex="-1">1. Overview <a class="header-anchor" href="#_1-overview" aria-label="Permalink to &quot;1. Overview&quot;">​</a></h2><p>Projects are the top-level organizational unit in Sanjeev AI, containing scripts, character maps, and settings.</p><h2 id="_2-data-structure" tabindex="-1">2. Data Structure <a class="header-anchor" href="#_2-data-structure" aria-label="Permalink to &quot;2. Data Structure&quot;">​</a></h2><ul><li><strong>Path</strong>: <code>users/{userId}/projects/{projectId}</code></li><li><strong>Fields</strong>: <code>name</code>, <code>createdAt</code>, <code>updatedAt</code>, <code>characterMap</code>, <code>locationMap</code>, <code>youtubePlaylistId</code>.</li><li><strong>Subcollections</strong>: <code>/scripts</code>, <code>/video_drafts</code>, <code>/workflows</code>.</li></ul><h2 id="_3-script-parsing" tabindex="-1">3. Script Parsing <a class="header-anchor" href="#_3-script-parsing" aria-label="Permalink to &quot;3. Script Parsing&quot;">​</a></h2><ul><li>The app supports importing raw <code>.txt</code>, <code>.md</code>, or Fountain formats.</li><li><strong>Parser Logic</strong>: A regex-based engine splits text by empty lines into chunks. If a chunk is prefixed with <code>[Speaker]:</code>, it extracts the speaker name and assigns it. Otherwise, it defaults to the <code>Narrator</code>.</li></ul><h2 id="_4-cloning-a-b-testing" tabindex="-1">4. Cloning &amp; A/B Testing <a class="header-anchor" href="#_4-cloning-a-b-testing" aria-label="Permalink to &quot;4. Cloning &amp; A/B Testing&quot;">​</a></h2><ul><li>Users can clone a script to test a different visual style (e.g., cinematic vs anime) without altering the original timeline.</li><li>Cloning performs a deep copy of the script document, the VibeMap, and the timeline array.</li></ul>',9)])])}const h=t(n,[["render",o]]);export{g as __pageData,h as default};
